function environment.getCharacter()
    local _, race, raceID = Call(UnitRace, "player")
    local _, class = Call(UnitClass, "player")
    class = class or Call(UnitClassBase, "player")
    return {
        faction = Text(Call(UnitFactionGroup, "player")),
        level = Call(UnitLevel, "player"),
        raceID = raceID,
        race = Text(race),
        class = type(class) == "string" and class:upper() or nil,
        inGroup = Call(IsInGroup),
        inRaid = Call(IsInRaid),
        mapID = environment.getCurrentMapID(),
        indoors = Call(IsIndoors),
        inInstance = Call(IsInInstance),
    }
end--[[APR_DIAG]]; environment.getCharacter = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterCharacter.lua:257:environment.getCharacter#30", environment.getCharacter)--[[/APR_DIAG]]

